import { z } from 'zod';

// Menu photos and the restaurant logo are stored as bare filenames
// (`restaurant.jpeg`, resolved against REACT_APP_API_URL + /images on the
// client), backend-relative paths (`/images/x.jpg`), or absolute URLs.
export const imageRefSchema = z
  .string()
  .max(500, 'Image reference is too long')
  .optional()
  .or(z.literal(''));

export const loginSchema = z.object({
  email: z.string().email('Invalid email address'),
  password: z.string().min(1, 'Password is required'),
});

export const registerSchema = z.object({
  name: z.string().min(1, 'Name is required'),
  email: z.string().email('Invalid email address'),
  password: z.string().min(6, 'Password must be at least 6 characters'),
  phone: z.string().optional(),
});

export const menuItemSchema = z.object({
  name: z.string().min(1, 'Name is required'),
  description: z.string().optional(),
  price: z.number().positive('Price must be positive'),
  category: z.string().min(1, 'Category is required'),
  image: imageRefSchema,
  available: z.boolean(),
});

export const orderFormSchema = z.object({
  tableNumber: z
    .string()
    .min(1, 'Table number is required')
    .refine((v) => Number.isInteger(Number(v)) && Number(v) > 0, {
      message: 'Table number is required',
    }),
});

export const reservationSchema = z.object({
  date: z.string().min(1, 'Date is required'),
  time: z.string().min(1, 'Time is required'),
  guests: z.number().int().positive('Guests must be at least 1'),
  tableNumber: z.number().int().positive().optional(),
  specialRequests: z.string().optional(),
  clientName: z.string().optional(),
  clientPhone: z.string().optional(),
  clientEmail: z.string().email('Invalid email').optional().or(z.literal('')),
  status: z.enum(['confirmed', 'completed', 'cancelled']).optional(),
});

export const restaurantSettingsSchema = z.object({
  name: z.string().min(1, 'Name is required'),
  logo: imageRefSchema,
  address: z.string().optional(),
  phone: z.string().optional(),
  email: z.string().email('Invalid email').optional().or(z.literal('')),
  tableCount: z.number().int().min(1, 'Table count must be at least 1'),
});

export const userFormSchema = z.object({
  name: z.string().min(1, 'Name is required'),
  email: z.string().email('Invalid email address'),
  password: z.string().min(6, 'Password must be at least 6 characters'),
  phone: z.string().optional(),
  role: z.enum(['customer', 'staff', 'admin']),
});

export const userUpdateSchema = z.object({
  name: z.string().min(1, 'Name is required'),
  email: z.string().email('Invalid email address'),
  phone: z.string().optional(),
  role: z.enum(['customer', 'staff', 'admin']),
  newPassword: z
    .string()
    .optional()
    .refine((v) => !v || v.length >= 6, { message: 'Password must be at least 6 characters' }),
});

export type LoginFormData = z.infer<typeof loginSchema>;
export type RegisterFormData = z.infer<typeof registerSchema>;
export type MenuItemFormData = z.infer<typeof menuItemSchema>;
export type OrderFormData = z.infer<typeof orderFormSchema>;
export type ReservationFormData = z.infer<typeof reservationSchema>;
export type RestaurantSettingsFormData = z.infer<typeof restaurantSettingsSchema>;
export type UserFormData = z.infer<typeof userFormSchema>;
export type UserUpdateFormData = z.infer<typeof userUpdateSchema>;
